                                        expected_head=state.head)
                except Refusal as refusal:
                    if refusal.reason != "stale_head":
                        raise
                    continue
                return fresh
            raise Refusal("contended", f"{event_id}: the ledger kept advancing during adjudication")

def f(self, content: ArchivedContent) -> Record:
