def f(self, rule: SourceRule) -> datetime:
        """The evidenced publication time, or the observer's read time for a source that evidences none."""
        if rule.publishes_evidenced_times:
            if self.record.evidenced_publication_time is None:
                raise Refusal("missing_publication_time", f"{self.record.record_id}: the source rule promises "
                              "evidenced publication times")
            return self.record.evidenced_publication_time
        return self.record.first_observed_at

functions.cpe.canonical.x__check_json:
def f(value: object, path: str, active: frozenset[int] = frozenset()) -> None:
    """Refuse anything that is not plain, finite, acyclic JSON data; ``active`` holds the containers on the current
    path, so a value that contains itself is a typed refusal rather than a RecursionError."""
    if value is None or isinstance(value, (bool, str)):
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise Refusal("non_finite_number", f"{path} is {value!r}")
        return
    if isinstance(value, (list, dict)):
        if id(value) in active:
            raise Refusal("cyclic_value", f"{path} contains itself")
        inner = active | {id(value)}
        if isinstance(value, list):
            for i, item in enumerate(value):
                _check_json(item, f"{path}[{i}]", inner)
            return
        for key, item in value.items():
            if not isinstance(key, str):
                raise Refusal("non_string_key", f"{path} has key {key!r}")
            _check_json(item, f"{path}.{key}", inner)
        return
    raise Refusal("not_json", f"{path} is of type {type(value).__name__}")

functions.cpe.canonical.x_canonical_bytes:
def f(value: JsonValue) -> bytes:
    """Return the one canonical UTF-8 byte form of ``value``.

    Refuses anything that is not plain JSON data, so that no object can carry hidden state into a digest.
    """
    _check_json(value, "$")
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False).encode("ascii")

functions.cpe.canonical.x_require_hex_digest:
def f(value: object, field: str) -> str:
    """Accept exactly 64 lowercase hex characters (fixture F-04: ``'z' * 64`` is refused)."""
    if not isinstance(value, str) or len(value) != SHA256_HEX_LENGTH or any(c not in "0123456789abcdef" for c in value):
        raise Refusal("invalid_digest", f"{field} must be {SHA256_HEX_LENGTH} lowercase hex characters")
    return value

functions.cpe.capability.gate.xǁCapabilityGateǁ_ab:
def f(self, intent_id: str, reason: str) -> Record:
        """Append the abort of a pending intent with its reading. The reading is taken without the discontinuity
        test: an abort only settles a consumed nonce and authorises nothing, and it must be writable right after
        a discontinuity has rotated the epoch."""
        def decide(state: GateState, now: datetime) -> Write:
            if intent_id not in state.pending_intents:  # decided against the current head, not a snapshot
                raise Refusal("intent_settled", f"{intent_id} is already committed or aborted")
            record = AbortRecord(intent_id, reason, self._raw_reading(now))
            return KIND_ABORT, _ledger_id("gate-abort", intent_id), record.to_payload()

        return self._append(decide)

functions.cpe.capability.gate.xǁCapabilityGateǁ_ap:
def f(self, decide: Decide, admit: Admit | None = None) -> Record:
        """One read-decide-write against the chain head the decision was taken on; a head that moved makes the
        decision recompute on the new state (another writer on the same ledger, this gate or another). ``admit``
        is checked by the ledger against the receipt the append assigns."""
        with self._lock:
            for _ in range(8):
                state = self.state()
                try:
                    now = self._ledger.now()
                except Refusal as refusal:
                    if refusal.reason == "clock_rollback":  # fails closed and is logged (item 2 "Clock", RC-37)
                        log.warning("clock rollback refused: %s", refusal)
                    raise
                kind, record_id, payload = decide(state, now)
                try:
                    return self._ledger.append(kind, record_id, payload, expected_head=state.head, admit=admit)
                except Refusal as refusal:
                    if refusal.reason == "clock_rollback":  # the append's own clock sample (4333626183)
                        log.warning("clock rollback refused: %s", refusal)
                    if refusal.reason != "stale_head":
                        raise
            raise Refusal("contended", "the ledger kept advancing while the record was being decided")

functions.cpe.capability.gate.xǁCapabilityGateǁ_in:
def f(capability: Capability) -> str:
        """The nonce's identity in the ledger: one intent per (epoch, nonce), enforced by the ledger's unique
        record identifier inside the writer transaction (RC-43)."""
