            member_event_ids=require_identifier_tuple(mapping["member_event_ids"], "member_event_ids", allow_empty=False),
            pre_declared_void=require_identifier_tuple(mapping.get("pre_declared_void", []), "pre_declared_void",
                                                       allow_empty=True),
